import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

export async function POST(req: Request) {
  try {
    const { className } = await req.json();
    const projectDir = process.cwd();
    
    // ✅ Update to use the IMPROVED timetable file
    const outputPath = path.join(projectDir, "all_classes_timetable.json");  // ✅ FIXED filename
    const inputDataPath = path.join(projectDir, "inputData.json");

    // 1️⃣ Read timetable JSON (already generated by Python)
    if (!fs.existsSync(outputPath)) {
      return NextResponse.json(
        { error: "Timetable file not found. Please run the Python script first." },
        { status: 404 }
      );
    }

    const timetableData = JSON.parse(fs.readFileSync(outputPath, "utf-8"));

    // 2️⃣ Extract timetable for selected class
    const timetable = timetableData[className];

    if (!timetable) {
      return NextResponse.json(
        { error: `No timetable found for class ${className}` },
        { status: 404 }
      );
    }

    // 3️⃣ Load inputData to get dynamic constraints
    let constraints = null;
    try {
      if (fs.existsSync(inputDataPath)) {
        const inputData = JSON.parse(fs.readFileSync(inputDataPath, "utf-8"));
        constraints = inputData.constraints;
        console.log('📥 Loaded constraints from inputData.json:', constraints);
      }
    } catch (err: unknown) {  // ✅ FIXED: Type the error
      console.warn('⚠️ Could not load inputData.json:', err);
    }

    // 4️⃣ Send timetable AND constraints back to frontend
    return NextResponse.json({ 
      timetable,
      constraints  // ✅ Include dynamic constraints
    });
  } catch (err: unknown) {  // ✅ FIXED: Type the error
    console.error("Error fetching timetable:", err);
    
    // ✅ FIXED: Safely access error message
    const errorMessage = err instanceof Error ? err.message : "Failed to fetch timetable";
    
    return NextResponse.json({ error: errorMessage }, { status: 500 });
  }
}
